-- Idempotent indexes; original tables and constraints remain unchanged.
CREATE INDEX IF NOT EXISTS astra_users_username_id ON users(username, id);
CREATE INDEX IF NOT EXISTS astra_users_region_active ON users(region, id) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS astra_login_sessions_active_token ON login_sessions(token_hash) INCLUDE (user_id, created_at) WHERE active = true;
CREATE INDEX IF NOT EXISTS astra_login_sessions_active_user ON login_sessions(user_id) WHERE active = true;
CREATE INDEX IF NOT EXISTS astra_administrator_sessions_active_token ON administrator_sessions(token_hash) WHERE active = true;
CREATE INDEX IF NOT EXISTS astra_administrator_sessions_active_user ON administrator_sessions(administrator_id) WHERE active = true;
CREATE INDEX IF NOT EXISTS astra_administrators_username ON administrators(username);
CREATE INDEX IF NOT EXISTS astra_friendships_low_page ON friendships(user_low_id, updated_at DESC, id DESC) INCLUDE (user_high_id);
CREATE INDEX IF NOT EXISTS astra_friendships_high_page ON friendships(user_high_id, updated_at DESC, id DESC) INCLUDE (user_low_id);
CREATE INDEX IF NOT EXISTS astra_follows_follower_page ON follows(follower_id, updated_at DESC, id DESC) INCLUDE (followee_id);
CREATE INDEX IF NOT EXISTS astra_follows_followee_page ON follows(followee_id, updated_at DESC, id DESC) INCLUDE (follower_id);
CREATE INDEX IF NOT EXISTS astra_block_relations_reverse ON block_relations(blocked_id, blocker_id);
CREATE INDEX IF NOT EXISTS astra_friend_requests_incoming ON friend_requests(recipient_id, updated_at DESC, id DESC) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS astra_friend_requests_outgoing ON friend_requests(requester_id, updated_at DESC, id DESC) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS astra_friend_requests_pair ON friend_requests(requester_id, recipient_id) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS astra_posts_author_window ON posts(author_id, posting_window_id);
CREATE INDEX IF NOT EXISTS astra_posts_author_page ON posts(author_id, posted_at DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS astra_posts_window_page ON posts(posting_window_id, posted_at DESC, id DESC) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS astra_posts_public_page ON posts(posted_at DESC, id DESC) WHERE deleted_at IS NULL AND visibility = 'public';
CREATE INDEX IF NOT EXISTS astra_users_profile_image ON users(profile_image_id) WHERE profile_image_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS astra_posts_image ON posts(image_id, author_id);
CREATE INDEX IF NOT EXISTS astra_posting_windows_date ON posting_windows(local_date, id);
CREATE INDEX IF NOT EXISTS astra_comments_post_page ON comments(post_id, created_at, id) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS astra_realmojis_post_page ON realmojis(post_id, created_at DESC, id DESC) WHERE replaced_at IS NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS astra_realmojis_image ON realmojis(image_id, reactor_id) INCLUDE (post_id, replaced_at, deleted_at);
CREATE INDEX IF NOT EXISTS astra_notifications_user_page ON notifications(user_id, created_at DESC, id DESC);
ANALYZE;
